from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class PuschTestResults(SchemaObject):
    time = SchemaField(name="time", not_null=True)
    detected_counter1 = SchemaField(name="detectedCounter1", not_null=True)
    missed_counter1 = SchemaField(name="missedCounter1", not_null=True)
    detected_counter2 = SchemaField(name="detectedCounter2", not_null=True)
    missed_counter2 = SchemaField(name="missedCounter2", not_null=True)
    rssi = SchemaField(name="rssi", not_null=True)
    throughput = SchemaField(name="throughput", not_null=True)
    received_bits = SchemaField(name="receivedBits", not_null=True)
    unreceived_bits = SchemaField(name="unreceivedBits", not_null=True)
    defective_bits = SchemaField(name="defectiveBits", not_null=True)
    received_blocks = SchemaField(name="receivedBlocks", not_null=True)
    unreceived_blocks = SchemaField(name="unreceivedBlocks", not_null=True)
    defective_blocks = SchemaField(name="defectiveBlocks", not_null=True)

    def __init__(self, time=None, detected_counter1=None, missed_counter1=None, detected_counter2=None,
                 missed_counter2=None, rssi=None, throughput=None, received_bits=None, unreceived_bits=None,
                 defective_bits=None, defective_blocks=None, received_blocks=None, unreceived_blocks=None):
        self.time = time
        self.detected_counter1 = detected_counter1
        self.missed_counter1 = missed_counter1
        self.detected_counter2 = detected_counter2
        self.missed_counter2 = missed_counter2
        self.rssi = rssi
        self.throughput = throughput
        self.received_bits = received_bits
        self.unreceived_bits = unreceived_bits
        self.defective_bits = defective_bits
        self.defective_blocks = defective_blocks
        self.received_blocks = received_blocks
        self.unreceived_blocks = unreceived_blocks


class PuschTestParams(SchemaObject):
    frc_index = SchemaField(name="frcIndex", not_null=True)
    phys_cell_id = SchemaField(name="physCellId", not_null=True)
    beam_pattern_id = SchemaField(name="beamPatternIdArray", not_null=True)
    prb_offset = SchemaField(name="prbOffset", not_null=True)
    reporting_time_interval = SchemaField(name="reportingTimeInterval", not_null=True)
    ru_mode = SchemaField(name="ruMode", not_null=True)
    nrarfcn = SchemaField(name="nrarfcn", optional=True)
    nrarfcn_ul = SchemaField(name="nrarfcnUl", optional=True)
    nrarfcn_dl = SchemaField(name="nrarfcnDl", optional=True)
    bb_selector = SchemaField(name="bbSelector", not_null=True)
    csi_payload_bit = SchemaField(name="csiPayloadBit", not_null=True)
    digital_out_rate = SchemaField(name="digitalOutRate", not_null=True)
    digital_out_type = SchemaField(name="digitalOutType", not_null=True)
    num_uci_bits = SchemaField(name="numUciBits", not_null=True)
    ul_dmrs_mapping_type = SchemaField(name="ulDmrsMappingType", not_null=True)
    digital_output_enable = SchemaField(name="digitalOutputEnable", not_null=True)
    act_high_speed_cell = SchemaField(name="actHighSpeedCell", not_null=True)

    def __init__(self, frc_index=None, phys_cell_id=None, beam_pattern_id=None, prb_offset=None,
                 reporting_time_interval=None, ru_mode=None, nrarfcn=None, bb_selector=None,
                 csi_payload_bit=None, digital_out_rate=None, digital_out_type=None, num_uci_bits=None,
                 ul_dmrs_mapping_type=None, nrarfcn_ul=None, nrarfcn_dl=None, digital_output_enable=None, act_high_speed_cell=None):
        self.frc_index = frc_index
        self.phys_cell_id = phys_cell_id
        self.beam_pattern_id = beam_pattern_id
        self.prb_offset = prb_offset
        self.reporting_time_interval = reporting_time_interval
        self.ru_mode = ru_mode
        self.nrarfcn = nrarfcn
        self.bb_selector = bb_selector
        self.csi_payload_bit = csi_payload_bit
        self.digital_out_rate = digital_out_rate
        self.digital_out_type = digital_out_type
        self.num_uci_bits = num_uci_bits
        self.ul_dmrs_mapping_type = ul_dmrs_mapping_type
        self.nrarfcn_dl = nrarfcn_dl
        self.nrarfcn_ul = nrarfcn_ul
        self.digital_output_enable = digital_output_enable
        self.act_high_speed_cell = act_high_speed_cell


class GetPuschCPCONFIGV1(SchemaObject):
    pusch_test_params = SchemaField(name="puschTestParams", klass=PuschTestParams)
    pusch_test_results = SchemaField(name="puschTestResults", klass=PuschTestResults, many=True)

    def __init__(self, pusch_test_params=None, pusch_test_results=None):
        self.pusch_test_params = pusch_test_params
        self.pusch_test_results = pusch_test_results

        super(GetPuschCPCONFIGV1, self).__init__()
